def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    symbols = list(dict.fromkeys(alphabet))
    k = len(symbols)
    pos = {ch: i for i, ch in enumerate(symbols)}

    trans = [[-1] * k]
    out = [False]

    def new_state() -> int:
        trans.append([-1] * k)
        out.append(False)
        return len(trans) - 1

    for word in banned:
        state = 0
        for ch in word:
            c = pos[ch]
            if trans[state][c] < 0:
                trans[state][c] = new_state()
            state = trans[state][c]
        out[state] = True

    fail = [0] * len(trans)
    queue = []
    for c in range(k):
        nxt = trans[0][c]
        if nxt < 0:
            trans[0][c] = 0
        else:
            queue.append(nxt)

    head = 0
    while head < len(queue):
        state = queue[head]
        head += 1
        for c in range(k):
            nxt = trans[state][c]
            if nxt < 0:
                trans[state][c] = trans[fail[state]][c]
            else:
                fail[nxt] = trans[fail[state]][c]
                if out[fail[nxt]]:
                    out[nxt] = True
                queue.append(nxt)

    for state in queue:
        if out[fail[state]]:
            out[state] = True

    good_states = [s for s in range(len(trans)) if not out[s]]
    index_of = {s: i for i, s in enumerate(good_states)}
    m = len(good_states)
    base = [[0] * m for _ in range(m)]
    for s in good_states:
        i = index_of[s]
        row = base[i]
        for c in range(k):
            j = index_of.get(trans[s][c])
            if j is not None:
                row[j] += 1

    def multiply(a, b):
        c = [[0] * m for _ in range(m)]
        for i in range(m):
            ai = a[i]
            ci = c[i]
            for t in range(m):
                ait = ai[t]
                if ait:
                    bt = b[t]
                    for j in range(m):
                        ci[j] = (ci[j] + ait * bt[j]) % MOD
        return c

    result = [[1 if i == j else 0 for j in range(m)] for i in range(m)]
    exp = n
    while exp:
        if exp & 1:
            result = multiply(result, base)
        base = multiply(base, base)
        exp >>= 1

    return sum(result[index_of[0]]) % MOD
